module Moderate
  class QuestionsController < BaseController
    before_action :set_quiz
    before_action :set_question, only: %i[edit update destroy move]

    def new
      @question = @quiz.questions.build(active: true)
      @rows = blank_rows(4)
      @errors = []
    end

    def create
      @question = @quiz.questions.build(question_params)
      @rows = option_rows_from_params

      return render_with_extra_row(:new) if params[:add_option]
      return render_without_row(:new) if params[:remove_option]

      if validate_input(@question, @rows) && save_with_options(@question, @rows, replace_options: false)
        redirect_to moderate_quiz_path(@quiz), notice: "Question added."
      else
        @errors << "The question could not be saved." if @errors.empty?
        render :new, status: :unprocessable_content
      end
    end

    def edit
      @rows = rows_from_options(@question.options)
      @errors = []
    end

    def update
      @question.assign_attributes(question_params)

      if params[:options]
        # Full form submit (from the question form).
        @rows = option_rows_from_params
        return render_with_extra_row(:edit) if params[:add_option]
        return render_without_row(:edit) if params[:remove_option]

        if validate_input(@question, @rows) && save_with_options(@question, @rows, replace_options: true)
          redirect_to moderate_quiz_path(@quiz), notice: "Question updated."
        else
          @errors << "The question could not be saved." if @errors.empty?
          render :edit, status: :unprocessable_content
        end
      else
        # Inline submit (e.g. the "Active" switch on the quiz page): keep the options as they are.
        if @question.save
          redirect_to moderate_quiz_path(@quiz, anchor: "question_#{@question.id}"), notice: "Question updated."
        else
          redirect_to moderate_quiz_path(@quiz, anchor: "question_#{@question.id}"), alert: "The question could not be updated."
        end
      end
    end

    def destroy
      @question.destroy
      redirect_to moderate_quiz_path(@quiz), notice: "Question deleted."
    end

    def move
      @question.move(params[:direction])
      redirect_to moderate_quiz_path(@quiz, anchor: "question_#{@question.id}")
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:quiz_id])
    end

    def set_question
      @question = @quiz.questions.find(params[:id])
    end

    def question_params
      params.expect(question: %i[body active])
    end

    def blank_rows(count)
      Array.new(count) { { body: "", correct: false } }
    end

    def rows_from_options(options)
      options.map { |option| { body: option.body, correct: option.correct? } }
    end

    # Rows posted from the form: options[0][body], options[0][correct], ...
    def option_rows_from_params
      raw = params[:options] || {}
      raw = raw.to_unsafe_h if raw.respond_to?(:to_unsafe_h)
      raw.sort_by { |index, _| index.to_i }.map do |_, attrs|
        attrs ||= {}
        {
          body: attrs["body"].to_s,
          correct: ActiveModel::Type::Boolean.new.cast(attrs["correct"])
        }
      end
    end

    def filled_rows(rows)
      rows.reject { |row| row[:body].blank? }
    end

    def validate_input(question, rows)
      @errors = []
      @errors << "Question can't be blank" if question.body.blank?

      filled = filled_rows(rows)
      @errors << "Add at least two options" if filled.size < 2
      @errors << "Mark at least one option as correct" if filled.none? { |row| row[:correct] }

      @errors.empty?
    end

    def save_with_options(question, rows, replace_options:)
      question.position = next_position if question.new_record?

      Question.transaction do
        question.save!
        question.options.destroy_all if replace_options
        filled_rows(rows).each_with_index do |row, index|
          question.options.create!(body: row[:body].strip, correct: row[:correct], position: index + 1)
        end
      end
      true
    rescue ActiveRecord::RecordInvalid
      false
    end

    def next_position
      (@quiz.questions.maximum(:position) || 0) + 1
    end

    def render_with_extra_row(view)
      @rows << { body: "", correct: false }
      @errors = []
      render view
    end

    def render_without_row(view)
      @rows.delete_at(params[:remove_option].to_i)
      @errors = []
      render view
    end
  end
end
