module Moderate
  # Lets the moderator try the quiz as a player would.
  # Stateless: the progress and the score travel in the query string,
  # preview answers are not stored anywhere.
  class PreviewsController < BaseController
    before_action :set_quiz

    def show
      @questions = @quiz.questions.where(active: true).includes(:options).to_a
      @total = @questions.size
      return if @total.zero?

      @index = params[:q].to_i.clamp(0, @total)
      @score = params[:c].to_i.clamp(0, @total)

      if @index >= @total
        render :score
        return
      end

      @question = @questions[@index]
      @picked = params[:pick].present? ? @question.options.detect { |option| option.id.to_s == params[:pick].to_s } : nil
      @next_score = @score + (@picked&.correct? ? 1 : 0)
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:id])
    end
  end
end
